========================================= */

:root {
  --charcoal: #242321;
  --charcoal-deep: #191816;
  --gold: #A77C48;
  --gold-light: #C5A477;
  --beige: #D4C2A8;
  --ivory: #F5F0E7;
  --walnut: #594536;
  --warm-grey: #77716A;
  --white: #FFFFFF;

  --header-height: 86px;

  --glass-dark: rgba(36, 35, 33, 0.68);
  --glass-border: rgba(255, 255, 255, 0.17);
  --glass-gold: rgba(197, 164, 119, 0.32);

  --shadow-glass:
    0 1px 0 rgba(255, 255, 255, 0.18) inset,
    0 -1px 0 rgba(0, 0, 0, 0.18) inset,
    0 12px 28px rgba(0, 0, 0, 0.22),
    0 25px 60px rgba(0, 0, 0, 0.16);
}

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  background: var(--ivory);
  color: var(--charcoal);
  font-family: Arial, Helvetica, sans-serif;
  -webkit-font-smoothing: antialiased;
}

a {
  color: inherit;
  text-decoration: none;
}

button {
  font: inherit;
  cursor: pointer;
}

::selection {
  background: var(--gold);
  color: white;
}

/* =========================================
   LEGACY HEADER SUPPORT (Site Header)
========================================= */

.md-header {
  position: sticky;
  top: 0;
  z-index: 999;
  width: 100%;
  color: var(--ivory);
  background: linear-gradient(120deg, rgba(255,255,255,0.10) 0%, rgba(36,35,33,0.78) 25%, rgba(36,35,33,0.62) 65%, rgba(197,164,119,0.12) 100%);
  backdrop-filter: blur(30px) saturate(170%);
  -webkit-backdrop-filter: blur(30px) saturate(170%);
  border-bottom: 1px solid var(--glass-border);
  box-shadow: var(--shadow-glass);
  isolation: isolate;
}

.md-topbar {
  position: relative;
  background: rgba(20,19,18,0.32);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border-bottom: 1px solid rgba(255,255,255,0.07);
}

.md-topbar-inner {
  width: 100%;
  max-width: 1500px;
  min-height: 31px;
  padding: 0 5.5%;
  margin: auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  color: var(--gold-light);
  font-size: 9px;
  letter-spacing: 2px;
}

.md-header-main {
  position: relative;
  width: 100%;
}

.md-header-inner {
  width: 100%;
  max-width: 1500px;
  min-height: var(--header-height);
  padding: 0 5.5%;
  margin: auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 25px;
}

.md-brand {
  display: flex;
  align-items: center;
  gap: 13px;
  flex-shrink: 0;
}

.md-brand-icon {
  width: 53px;
  height: 53px;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
  background: linear-gradient(145deg, rgba(255,255,255,0.17), rgba(197,164,119,0.12) 50%, rgba(0,0,0,0.25));
  border: 1px solid rgba(197,164,119,0.75);
  box-shadow: 0 1px 0 rgba(255,255,255,0.4) inset, 0 -3px 6px rgba(0,0,0,0.3) inset, 0 5px 12px rgba(0,0,0,0.25), 0 0 20px rgba(197,164,119,0.12);
}

.md-brand-icon::before {
  content: "";
  position: absolute;
  inset: 4px;
  border: 1px solid rgba(197,164,119,0.4);
}

.md-brand-icon span {
  position: relative;
  z-index: 1;
  font-family: Georgia, serif;
  font-size: 21px;
  letter-spacing: -2px;
  background: linear-gradient(135deg, #F5E4C6, #A77C48 45%, #F5E4C6);
  background-clip: text;
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  filter: drop-shadow(0 2px 2px rgba(0,0,0,.4));
}

.md-brand-text {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.md-brand-name {
  color: var(--ivory);
  font-size: 14px;
  font-weight: 600;
  letter-spacing: 2px;
  white-space: nowrap;
}

.md-brand-name span {
  color: var(--gold-light);
}

.md-brand-tagline {
  color: #B8A58D;
  font-size: 8px;
  letter-spacing: 3px;
}

.md-desktop-nav {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: clamp(16px, 2.3vw, 34px);
  height: var(--header-height);
}

.md-nav-link {
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: 7px;
  height: 100%;
  padding: 0;
  border: 0;
  background: none;
  color: #E4DED4;
  font-size: 12px;
  font-weight: 500;
  letter-spacing: .5px;
  white-space: nowrap;
  transform: translateZ(0);
  transition: color .3s ease, transform .3s ease, text-shadow .3s ease;
}

.md-nav-link::after {
  content: "";
  position: absolute;
  bottom: 23px;
  left: 0;
  width: 0;
  height: 2px;
  background: linear-gradient(90deg, var(--gold), var(--gold-light));
  box-shadow: 0 0 10px rgba(197,164,119,.5);
  transition: width .3s ease;
}

.md-nav-link:hover,
.md-nav-link.active {
  color: #E6C79C;
}

.md-nav-link:hover {
  transform: translateY(-3px);
  text-shadow: 0 3px 12px rgba(197,164,119,.3);
}

.md-nav-link:hover::after,
.md-nav-link.active::after {
  width: 100%;
}

/* =========================================
   FOOTER
========================================= */

.site-footer {
  background: var(--charcoal);
  color: #e8e0d5;
  padding: 75px 6% 0;
}

.footer-main {
  width: min(1440px, 100%);
  margin: auto;
  display: grid;
  grid-template-columns: 1.5fr 1fr 1.3fr 1.4fr;
  gap: 55px;
  padding-bottom: 65px;
}

.brand, .footer-logo {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  flex-shrink: 0;
}

.brand-mark {
  width: 46px;
  height: 46px;
  display: grid;
  place-items: center;
  border: 1px solid var(--gold);
  color: var(--gold-light);
  font-family: Georgia, serif;
  font-size: 20px;
  letter-spacing: -2px;
}

.brand-copy {
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.brand-name {
  color: var(--ivory);
  font-size: 14px;
  font-weight: 700;
  letter-spacing: 2px;
  white-space: nowrap;
}

.brand-tagline {
  color: var(--gold-light);
  font-size: 8px;
  letter-spacing: 2.4px;
}

.footer-brand > p {
  max-width: 300px;
  margin-top: 24px;
  color: #aaa39a;
  font-size: 13px;
  line-height: 1.9;
}

.footer-socials {
  display: flex;
  gap: 12px;
  margin-top: 22px;
}

.footer-socials a {
  width: 36px;
  height: 36px;
  display: grid;
  place-items: center;
  border: 1px solid #555047;
  color: var(--gold-light);
  transition: all .2s ease;
}

.footer-socials a:hover {
  background: var(--gold);
  color: white;
  transform: translateY(-3px);
}

.footer-column {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 16px;
}

.footer-column h3 {
  margin: 0 0 10px;
  color: var(--gold-light);
  font-family: Georgia, serif;
  font-size: 18px;
  font-weight: 400;
}

.footer-column > a,
.footer-column > p {
  display: flex;
  align-items: center;
  gap: 10px;
  margin: 0;
  color: #aaa39a;
  font-size: 12px;
  transition: color .2s ease;
}

.footer-column > a:hover {
  color: var(--gold-light);
}

.footer-contact-link {
  margin-top: 10px;
  color: var(--gold-light) !important;
}

.footer-bottom {
  width: min(1440px, 100%);
  min-height: 70px;
  margin: auto;
  border-top: 1px solid rgba(197,164,119,.2);
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 20px;
  color: #8e887f;
  font-size: 11px;
}

/* =========================================
   NEW FLOATING GLASS CAPSULE HEADER (fh- prefix)
========================================= */

.fh-wrapper {
  position: fixed;
  top: 20px;
  left: 0;
  right: 0;
  z-index: 999;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 0 24px;
  pointer-events: none;
  color: var(--ivory);
  font-family: Arial, Helvetica, sans-serif;
}

.fh-bar {
  pointer-events: auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 28px;
  width: 100%;
  max-width: 1320px;
  padding: 10px 12px 10px 18px;
  background: linear-gradient(120deg, rgba(255, 255, 255, 0.10) 0%, rgba(36, 35, 33, 0.86) 25%, rgba(36, 35, 33, 0.72) 65%, rgba(197, 164, 119, 0.14) 100%);
  backdrop-filter: blur(30px) saturate(170%);
  -webkit-backdrop-filter: blur(30px) saturate(170%);
  border: 1px solid var(--glass-border);
  border-radius: 9999px;
  box-shadow: 0 1px 0 rgba(255, 255, 255, 0.18) inset, 0 -1px 0 rgba(0, 0, 0, 0.18) inset, 0 12px 28px rgba(0, 0, 0, 0.28), 0 25px 60px rgba(0, 0, 0, 0.18);
  position: relative;
  isolation: isolate;
  transition: box-shadow 0.3s ease, border-color 0.3s ease;
}

.fh-bar::before {
  content: "";
  position: absolute;
  top: 0;
  left: 6%;
  width: 88%;
  height: 1px;
  pointer-events: none;
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.65), rgba(197, 164, 119, 0.65), transparent);
}

.fh-bar::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -1;
  border-radius: inherit;
  pointer-events: none;
  background: linear-gradient(115deg, rgba(255, 255, 255, 0.12), transparent 24%, transparent 66%, rgba(197, 164, 119, 0.10));
}

.fh-brand {
  display: flex;
  align-items: center;
  gap: 12px;
  text-decoration: none;
  flex-shrink: 0;
  padding-left: 4px;
}







.fh-brand-text {
  display: flex;
  flex-direction: column;
  gap: 4px;
  line-height: 1.1;
}

.fh-brand-name {
  color: var(--ivory);
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 2px;
  white-space: nowrap;
}

.fh-brand-name span {
  color: var(--gold-light);
}

.fh-brand-tagline {
  color: #b8a58d;
  font-size: 7.5px;
  letter-spacing: 3px;
}

.fh-desktop-nav {
  display: flex;
  align-items: center;
  gap: 4px;
  flex: 1;
  justify-content: center;
}

.fh-nav-link {
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 10px 16px;
  border-radius: 9999px;
  border: 0;
  background: none;
  color: #e4ded4;
  font-size: 12px;
  font-weight: 500;
  letter-spacing: 0.5px;
  white-space: nowrap;
  text-decoration: none;
  transition: color 0.25s ease, background 0.25s ease, transform 0.25s ease;
}

.fh-nav-link:hover {
  color: var(--gold-light);
  background: rgba(197, 164, 119, 0.10);
  transform: translateY(-1px);
}

.fh-nav-link.active {
  color: var(--gold-light);
}

.fh-nav-link.active::after {
  content: "";
  position: absolute;
  bottom: 5px;
  left: 50%;
  transform: translateX(-50%);
  width: 18px;
  height: 2px;
  border-radius: 2px;
  background: linear-gradient(90deg, var(--gold), var(--gold-light));
  box-shadow: 0 0 10px rgba(197, 164, 119, 0.6);
}

.fh-cta {
  position: relative;
  overflow: hidden;
  display: inline-flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  min-width: 158px;
  height: 44px;
  padding: 0 8px 0 20px;
  border-radius: 9999px;
  border: 1px solid rgba(255, 255, 255, 0.3);
  background: linear-gradient(135deg, #d9b98c, #b18a58, #987044);
  color: #ffffff;
  font-size: 12px;
  font-weight: 500;
  letter-spacing: 0.4px;
  text-decoration: none;
  white-space: nowrap;
  flex-shrink: 0;
  box-shadow: 0 4px 12px rgba(100, 70, 35, 0.18);
  transition: all 0.3s ease;
}

.fh-cta::before {
  content: "";
  position: absolute;
  top: 0;
  left: -120%;
  width: 70%;
  height: 100%;
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.35), transparent);
  transform: skewX(-25deg);
  transition: left 0.6s ease;
}

.fh-cta:hover::before {
  left: 150%;
}

.fh-cta:hover {
  transform: translateY(-2px);
  filter: brightness(1.08);
  box-shadow: 0 6px 16px rgba(100, 70, 35, 0.25);
}

.fh-cta-icon {
  width: 30px;
  height: 30px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.15);
}

.fh-services-dropdown {
  position: relative;
}

.fh-services-trigger svg {
  transition: transform 0.3s ease;
}

.rotated {
  transform: rotate(180deg);
}

.fh-dropdown-panel {
  position: absolute;
  top: calc(100% + 16px);
  left: 50%;
  transform: translateX(-50%) translateY(10px);
  width: 310px;
  padding: 18px;
  background: linear-gradient(145deg, rgba(70, 65, 57, 0.94), rgba(36, 35, 33, 0.97));
  backdrop-filter: blur(32px) saturate(170%);
  -webkit-backdrop-filter: blur(32px) saturate(170%);
  border: 1px solid rgba(255, 255, 255, 0.17);
  border-top: 2px solid var(--gold-light);
  border-radius: 18px;
  box-shadow: 0 1px 0 rgba(255, 255, 255, 0.16) inset, 0 -1px 0 rgba(0, 0, 0, 0.2) inset, 0 15px 25px rgba(0, 0, 0, 0.2), 0 30px 60px rgba(0, 0, 0, 0.35);
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.25s ease, transform 0.3s ease, visibility 0.25s ease;
}

.fh-dropdown-panel.open {
  opacity: 1;
  visibility: visible;
  transform: translateX(-50%) translateY(0);
}

.fh-dropdown-heading {
  padding: 4px 8px 14px;
  border-bottom: 1px solid rgba(197, 164, 119, 0.2);
}

.fh-dropdown-heading span {
  color: var(--gold-light);
  font-size: 9px;
  letter-spacing: 2px;
}

.fh-dropdown-heading p {
  margin: 7px 0 0;
  color: var(--ivory);
  font-family: Georgia, serif;
  font-size: 19px;
}

.fh-dropdown-link {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 8px;
  color: #d9d0c3;
  font-size: 11.5px;
  text-decoration: none;
  border-bottom: 1px solid rgba(197, 164, 119, 0.08);
  transition: padding 0.25s ease, color 0.25s ease, background 0.25s ease;
}

.fh-dropdown-link svg {
  margin-left: auto;
  color: var(--gold-light);
  opacity: 0;
  transition: opacity 0.2s ease;
}

.fh-dropdown-link:hover {
  padding-left: 13px;
  color: var(--gold-light);
  background: rgba(255, 255, 255, 0.035);
}

.fh-dropdown-link:hover svg {
  opacity: 1;
}

.fh-dropdown-number {
  color: var(--gold-light);
  font-family: Georgia, serif;
  font-size: 11px;
}

.fh-dropdown-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 12px;
  padding: 12px 8px;
  color: var(--gold-light);
  font-size: 11px;
  letter-spacing: 0.5px;
  text-decoration: none;
  border-radius: 8px;
}

.fh-dropdown-footer:hover {
  background: rgba(197, 164, 119, 0.08);
}

.fh-mobile-toggle {
  display: none;
  align-items: center;
  justify-content: center;
  width: 43px;
  height: 43px;
  border-radius: 50%;
  border: 1px solid rgba(197, 164, 119, 0.45);
  background: linear-gradient(145deg, rgba(197, 164, 119, 0.22), rgba(255, 255, 255, 0.04));
  color: var(--gold-light);
  cursor: pointer;
  flex-shrink: 0;
  box-shadow: 0 1px 0 rgba(255, 255, 255, 0.2) inset, 0 5px 12px rgba(0, 0, 0, 0.2);
}

.fh-mobile-menu {
  pointer-events: auto;
  display: none;
  flex-direction: column;
  gap: 2px;
  width: 100%;
  max-width: 1320px;
  margin: 10px auto 0;
  padding: 14px 16px 20px;
  background: linear-gradient(145deg, rgba(65, 60, 53, 0.96), rgba(30, 29, 27, 0.98));
  backdrop-filter: blur(30px) saturate(170%);
  -webkit-backdrop-filter: blur(30px) saturate(170%);
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: 24px;
  box-shadow: 0 1px 0 rgba(255, 255, 255, 0.1) inset, 0 20px 45px rgba(0, 0, 0, 0.3);
}

@media (max-width: 900px) {
  .fh-mobile-menu.open {
    display: flex;
  }
}

.fh-mobile-topbar {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 6px 14px;
  margin-bottom: 4px;
  border-bottom: 1px solid rgba(197, 164, 119, 0.18);
  color: var(--gold-light);
  font-size: 8.5px;
  letter-spacing: 2px;
}

.fh-mobile-menu > a,
.fh-mobile-service-trigger {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 50px;
  padding: 0 6px;
  border: 0;
  border-bottom: 1px solid rgba(197, 164, 119, 0.13);
  background: transparent;
  color: #e8e0d5;
  font-size: 13px;
  text-align: left;
  text-decoration: none;
  transition: color 0.2s ease;
}

.fh-mobile-menu > a:hover,
.fh-mobile-menu > a.mobile-active,
.fh-mobile-service-trigger:hover {
  color: var(--gold-light);
}

.fh-mobile-services {
  display: flex;
  flex-direction: column;
  padding: 8px 0 8px 18px;
  background: rgba(255, 255, 255, 0.04);
}

.fh-mobile-services a {
  padding: 11px 8px;
  color: #c9bba7;
  font-size: 12px;
  text-decoration: none;
}

.fh-mobile-cta {
  display: flex !important;
  align-items: center;
  justify-content: center;
  gap: 8px;
  margin-top: 18px;
  padding: 14px !important;
  border-radius: 9999px !important;
  background: linear-gradient(135deg, #e0c093, #a77c48, #8c6337) !important;
  color: white !important;
  font-weight: 600;
  text-decoration: none;
  box-shadow: 0 6px 18px rgba(167, 124, 72, 0.35);
}

.fh-mobile-footer {
  margin-top: 12px;
  padding-top: 14px;
  border-top: 1px solid rgba(197, 164, 119, 0.14);
  color: var(--gold-light);
  font-size: 8.5px;
  letter-spacing: 1.6px;
  text-align: center;
}

.fh-spacer {
  height: 92px;
}

/* =========================================
   RESPONSIVE
========================================= */

@media (max-width: 1100px) {
  .fh-bar {
    gap: 18px;
    padding: 9px 10px 9px 16px;
  }
  .fh-nav-link {
    padding: 9px 13px;
    font-size: 11.5px;
  }
  .fh-cta {
    min-width: 138px;
    font-size: 11px;
  }
  
  .md-header-inner {
    padding: 0 3%;
    gap: 15px;
  }
  .md-desktop-nav {
    gap: 17px;
  }
  .md-nav-link {
    font-size: 11px;
  }
  .md-brand-name {
    font-size: 12px;
  }
  .md-header-cta {
    min-width: 125px;
  }
  .footer-main {
    grid-template-columns: 1fr 1fr;
  }
}

@media (max-width: 900px) {
  .fh-desktop-nav,
  .fh-cta {
    display: none;
  }
  .fh-mobile-toggle {
    display: flex;
  }
  .fh-wrapper {
    top: 12px;
    padding: 0 14px;
  }
  .fh-bar {
    padding: 8px 8px 8px 14px;
    gap: 14px;
  }
  .fh-brand-tagline {
    display: none;
  }
  .fh-spacer {
    height: 82px;
  }
}

@media (max-width: 760px) {
  .footer-main {
    grid-template-columns: 1fr 1fr;
    gap: 40px 22px;
  }
  .footer-bottom {
    flex-direction: column;
    justify-content: center;
    align-items: flex-start;
    padding: 18px 0;
    gap: 8px;
  }
}

@media (max-width: 420px) {
  .footer-main {
    grid-template-columns: 1fr;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    transition-duration: .01ms !important;
    animation-duration: .01ms !important;
  }
}

/* =========================================
   INFINITE MARQUEE ANIMATION
========================================= */
@keyframes scroll {
  0% {
    transform: translateX(0);
  }
  100% {
    transform: translateX(-50%); /* Kyunki humne items double kiye hain */
  }
}

.animate-scroll {
  animation: scroll 35s linear infinite;
}

/* Jab user mouse le jaye toh scroll rok do */
.group:hover .animate-scroll {
  animation-play-state: paused;
}

