/* CINEMATIC HERO START */

[data-video-hero="true"] {
  position: relative;
  isolation: isolate;
  display: grid;
  place-items: center;
  width: 100%;
  min-height: 90svh;
  padding: 60px 24px;
  overflow: hidden;
  background: #242321;
}

.hero-video-background {
  position: absolute;
  inset: 0;
  z-index: 1;
  overflow: hidden;
  pointer-events: none;
}

.hero-video-background video {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center;
  display: block;
}

.hero-video-background::after {
  content: "";
  position: absolute;
  inset: 0;
  background: rgba(15, 12, 9, 0.28);
}

[data-video-hero="true"] > div:not(.hero-video-background):not(:has(h1)) {
  position: absolute;
  inset: 0;
  z-index: 0;
  pointer-events: none;
}

[data-video-hero="true"] > div:has(h1) {
  position: relative;
  z-index: 3;
  grid-area: 1 / 1;
  width: min(100%, 1050px);
  margin: auto;
  padding: 60px 35px;
  text-align: center;
  background: rgba(255, 255, 255, 0.10);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border: 1px solid rgba(255, 255, 255, 0.24);
  border-radius: 30px;
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.22);
}

[data-video-hero="true"] a {
  color: #ffffff;
}

@media (max-width: 768px) {
  [data-video-hero="true"] {
    min-height: 85svh;
    padding: 35px 16px;
  }

  [data-video-hero="true"] > div:has(h1) {
    padding: 40px 20px;
    border-radius: 22px;
  }
}

/* CINEMATIC HERO END */

/* FLOATING SUPPORT START */

.support-widget {
  position: fixed;
  right: 24px;
  bottom: 24px;
  z-index: 1000;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 16px;
}

.floating-support-gif {
  position: relative;
  width: 85px;
  height: 85px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: #fff;
  border: 0;
  overflow: hidden;
  cursor: pointer;
  box-shadow: 0 8px 30px rgba(0,0,0,.18);
  transition: transform .3s ease;
}

.floating-support-gif img {
  width: 100%;
  height: 100%;
  object-fit: contain;
}

.floating-support-gif:hover {
  transform: scale(1.06);
}

.support-popup {
  width: min(340px, calc(100vw - 32px));
  background: #fff;
  border-radius: 22px;
  overflow: hidden;
  border: 1px solid rgba(197,164,119,.35);
  box-shadow: 0 20px 60px rgba(0,0,0,.25);
  animation: supportEnter .3s ease;
}

.support-header {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 18px;
  background: #242321;
  color: #fff;
}

.support-avatar {
  width: 42px;
  height: 42px;
  border-radius: 50%;
  background: #a77c48;
  display: grid;
  place-items: center;
  font-family: Georgia, serif;
}

.support-heading {
  display: flex;
  flex-direction: column;
  gap: 4px;
  flex: 1;
  font-size: 14px;
}

.support-heading span {
  font-size: 11px;
  color: #d4c2a8;
}

.support-header button {
  background: transparent;
  border: 0;
  color: white;
  cursor: pointer;
}

.support-body {
  padding: 18px;
  background: #f7f7f7;
}

.support-message {
  padding: 15px;
  border-radius: 12px;
  background: #fff;
  color: #444;
  font-size: 13px;
  line-height: 1.7;
  margin-bottom: 15px;
}

.support-call,
.support-whatsapp {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 14px;
  border-radius: 12px;
  color: #fff !important;
  text-decoration: none;
  font-size: 14px;
  margin-top: 10px;
  transition: filter .2s ease;
}

.support-call {
  background: #a77c48;
}

.support-whatsapp {
  background: #128c7e;
}

.support-call:hover,
.support-whatsapp:hover {
  filter: brightness(1.1);
}

@keyframes supportEnter {
  from {
    opacity: 0;
    transform: translateY(15px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@media (max-width: 768px) {
