/* ABOUT SLIDESHOW START */

.hs-about > .hs-about-slideshow {
  position: relative;
  height: 430px;
  overflow: hidden;
  border-radius: 22px;
  background: #c9b7a3;
  isolation: isolate;
  box-shadow: 0 18px 45px rgba(36,35,33,.14);
}

.hs-about-slideshow .about-slide-image {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center;
  opacity: 0;
  transform: scale(1.06);
  transition:
    opacity 1.25s ease-in-out,
    transform 5s ease-out;
}

.hs-about-slideshow .about-slide-image.is-active {
  opacity: 1;
  transform: scale(1);
}

.about-slide-overlay {
  position: absolute;
  inset: auto 0 0;
  z-index: 5;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 26px 22px 16px;
  background: linear-gradient(
    to top,
    rgba(0,0,0,.58),
    transparent
  );
  color: white;
  font-size: 10px;
  letter-spacing: 2px;
  pointer-events: none;
}

@media (max-width: 768px) {
  .hs-about > .hs-about-slideshow {
    height: 300px;
    border-radius: 16px;
  }

  .about-slide-overlay {
    padding: 20px 14px 12px;
    font-size: 9px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .hs-about-slideshow .about-slide-image {
    transition: none;
    transform: none;
  }
}

/* ABOUT SLIDESHOW END */
